#!/bin/sh
# Generated by Omega. Runs `mojo "$@"` in the pixi project in the current folder, without the
# report Modular's activation script sends the first time an environment is activated. The
# script ignores MODULAR_TELEMETRY_ENABLED and only checks for share/max/firstActivation, so that
# file is created first. If that can't be trusted to work, the activation is skipped altogether.
export MODULAR_TELEMETRY_ENABLED=0 MODULAR_CRASH_REPORTING_ENABLED=0
unset MODULAR_HOME

manifest=pixi.toml
[ -f "$manifest" ] || manifest=mojoproject.toml

die() {
  printf 'omega: %s\n' "$1" >&2
  exit 1
}

# The environment's mojo, without activating it.
direct() {
  prefix=$1
  shift
  [ -x "$prefix/bin/mojo" ] || die "no mojo in $prefix"
  export MODULAR_HOME="$prefix/share/max"
  exec "$prefix/bin/mojo" "$@"
}

# The only environment with a mojo, for when pixi can't say which one to use.
only_env() {
  set -- .pixi/envs/*/bin/mojo
  [ "$#" -eq 1 ] && [ -x "$1" ] || return 1
  (cd -P -- "${1%/bin/mojo}" && pwd -P)
}

# Prints "<env> <has a task called mojo>": default if it has Mojo, else the only one that does.
pick_env() {
  pixi info --manifest-path "$manifest" --json 2>/dev/null | awk '
    function flush() { if (name != "" && mojo) { n++; names[n] = name; tasks[n] = task } }
    /^  "environments_info": \[/ { on = 1; next }
    !on { next }
    /^  \]/ { on = 0; next }
    /^      "name": "/ { flush(); name = $0; sub(/^[^:]*: "/, "", name); sub(/",?$/, "", name); mojo = 0; task = 0; sec = ""; next }
    /^      "dependencies": \[$/ { sec = "deps"; next }
    /^      "tasks": \[$/ { sec = "tasks"; next }
    /^      \]/ { sec = ""; next }
    sec == "deps" && /^        "(mojo|mojo-compiler|modular)",?$/ { mojo = 1 }
    sec == "tasks" && /^        "mojo",?$/ { task = 1 }
    END {
      flush()
      for (i = 1; i <= n; i++) if (names[i] == "default") { print names[i], tasks[i]; exit }
      if (n == 1) print names[1], tasks[1]
    }'
}

# What marks an activation script as able to reach the network or run other code (lowercase).
word='(^|[^a-z0-9_])(nc|ncat|socat|telnet|ssh|scp|ftp|python[0-9.]*|perl|ruby|node|php|lua|eval|base64)([^a-z0-9_]|$)'
risky="telemetry|curl|wget|http|modular\\.com|socket|/dev/tcp|/dev/udp|$word"

# True if everything risky in this activation script is inside the block that
# `share/max/firstActivation` switches off.
guarded() {
  grep -Fxq 'export MODULAR_HOME="${CONDA_PREFIX}/share/max"' "$1" || return 1
  RISKY=$risky awk '
    $0 == "if ! [[ -f \"${MODULAR_HOME}/firstActivation\" ]]; then" { if (state) bad = 1; state = 1; next }
    state == 1 && /^fi[ \t]*$/ { state = 2; next }
    state != 1 && tolower($0) ~ ENVIRON["RISKY"] { bad = 1 }
    END { exit (bad || state != 2) }' "$1"
}

picked=$(pick_env)
env=${picked% *}
task=${picked##* }
case "$env" in
  "" | -* | *[!a-z0-9-]*)
    prefix=$(only_env) || die "can't tell which pixi environment has Mojo"
    direct "$prefix" "$@"
    ;;
esac

# A failed install stops here: nothing runs in a half-installed environment.
pixi install --manifest-path "$manifest" -e "$env" || exit $?

root=$(pwd -P)
prefix=$(cd -P -- ".pixi/envs/$env" 2>/dev/null && pwd -P) || die "pixi environment $env not found"
[ -x "$prefix/bin/mojo" ] || die "no mojo in pixi environment $env"

# A project task called mojo would replace the compiler in `pixi run mojo`.
[ "$task" = 0 ] || direct "$prefix" "$@"
# The marker is only ever written inside this project's .pixi.
case "$prefix/" in
  "$root/.pixi/"*) ;;
  *) direct "$prefix" "$@" ;;
esac

found=0
for script in "$prefix"/etc/conda/activate.d/*; do
  [ -f "$script" ] || continue
  # 1 is "nothing risky"; anything else, like an unreadable file, doesn't count as harmless.
  grep -Eqi -- "$risky" "$script"
  case $? in
    0) guarded "$script" || direct "$prefix" "$@"; found=1 ;;
    1) ;;
    *) direct "$prefix" "$@" ;;
  esac
done

if [ "$found" = 1 ]; then
  dir=$(cd -P -- "$prefix/share/max" 2>/dev/null && pwd -P) || direct "$prefix" "$@"
  marker=$dir/firstActivation
  [ "$dir" = "$prefix/share/max" ] && [ ! -L "$marker" ] || direct "$prefix" "$@"
  [ -e "$marker" ] || touch "$marker" 2>/dev/null || direct "$prefix" "$@"
  [ -f "$marker" ] || direct "$prefix" "$@"
fi

# --as-is: no re-sync between here and the activation, which could recreate the environment.
exec pixi run --manifest-path "$manifest" --as-is -e "$env" -- mojo "$@"
